/** 工具返回畸形结构时：**不许炸、也不许糊**（2026-10-23 实测出来的两半）。
 *
 *  缺陷形状（实测，不是推理）：工具返回 `{ok:true}`（缺 `output`）时
 *   ① `stuck.ts#stuckObservationOf` 直接 `.slice` ⇒ `TypeError: Cannot read properties of
 *      undefined (reading 'slice')` **把整轮任务打死**；
 *   ② 修掉崩溃之后，落盘的是字面量 `"undefined"` —— 模型拿到一条"有回执但读不懂"的
 *      tool_result，比明说"这条回执没有正文"更坏。
 *
 *  类型上 `ToolResult.output: string` 是必填，但那只约束**我们自己的**工具；
 *  插件工具、MCP 工具与脚本化工具都是运行期才拿到的，返回 `{ok:true}` / `output:null` /
 *  `output:{…}` 都完全可能（`base.ts` 的接口管不到跨进程边界）。
 *
 *  本组钉四件事：
 *    ① 畸形 output **不许炸整轮**（loop 正常收尾）；
 *    ② 畸形 output 的回执要**可读**（不是 `"undefined"` / `"[object Object]"`）；
 *    ③ 不同畸形要**分得开**（缺失 ≠ null ≠ 对象 ≠ 真空串）；
 *    ④ 正常字符串输出**逐字不变**（这条挡的是"为了安全把所有输出都包一层"）。
 */
import { describe, expect, it } from "vitest";
import { runLoop } from "../src/agent/loop";
import { stuckObservationOf } from "../src/agent/stuck";
import { projectContext } from "../src/agent/context";
import type { AgentEvent } from "../src/events";
import type { Provider, ProviderMessage } from "../src/providers";

/** 跑一轮：工具返回给定值，然后把**模型面看到的 tool 消息**取回来。 */
async function runOne(ret: unknown): Promise<{ threw: string; toolContent: string | undefined; events: AgentEvent[] }> {
  const events: AgentEvent[] = [];
  const requests: ProviderMessage[][] = [];
  let round = 0;
  const provider: Provider = {
    async *stream(messages) {
      requests.push(messages);
      round += 1;
      if (round === 1) yield { type: "tool_call", id: "c1", name: "t", args: {} };
      else yield { type: "assistant_message", content: "收尾" };
    },
  };
  let threw = "";
  try {
    await runLoop({
      provider,
      events: { async append(e: AgentEvent) { events.push(e); } },
      workspace: "/tmp",
      userMessage: "x",
      tools: { t: { name: "t", async run() { return ret as never; } } },
    });
  } catch (err) { threw = (err as Error).message; }
  const toolMsg = projectContext(events).find((m) => m.role === "tool");
  return { threw, toolContent: toolMsg === undefined ? undefined : String(toolMsg.content), events };
}

describe("工具返回畸形结构：不炸、不糊、分得开", () => {
  it("★ 缺 output（`{ok:true}`）⇒ 不许炸整轮，且回执可读", async () => {
    const r = await runOne({ ok: true });
    // 旧实现死在这一条：TypeError … reading 'slice'
    expect(r.threw, "一条诊断读数把整轮任务打死 = 本末倒置").toBe("");
    expect(r.toolContent).toContain("没有正文");
    expect(r.toolContent, "字面量 \"undefined\" 会被模型当成真实输出读").not.toBe("undefined");
  });

  it("★ output = null ⇒ 回执可读，且与「缺失」分得开", async () => {
    const r = await runOne({ ok: true, output: null });
    expect(r.threw).toBe("");
    expect(r.toolContent).toContain("null");
    expect(r.toolContent).not.toContain("undefined");
  });

  it("★ output = 对象 ⇒ **序列化出来**（不是 [object Object]）", async () => {
    const r = await runOne({ ok: true, output: { a: 1, b: "x" } });
    expect(r.threw).toBe("");
    expect(r.toolContent, "[object Object] 等于把回执扔了").not.toContain("[object Object]");
    expect(r.toolContent).toContain('"a":1');
  });

  it("★ 反向哨兵：正常字符串输出**逐字不变**（不许为了安全全包一层）", async () => {
    const r = await runOne({ ok: true, output: "文件读到了：42 行" });
    expect(r.toolContent).toBe("文件读到了：42 行");
  });

  it("真空串 ≠ 缺失（空串是『真的没输出』这一事实，不许被顶替成占位符）", async () => {
    const r = await runOne({ ok: true, output: "" });
    expect(r.toolContent).toBe("");
  });
});

describe("stuckObservationOf 的取料面（崩溃点本体）", () => {
  it("★ 非字符串一律不抛（旧实现 undefined.slice ⇒ TypeError）", () => {
    for (const v of [undefined, null, 42, {}, [], { a: 1 }]) {
      expect(() => stuckObservationOf(v), "stuckObservationOf(" + JSON.stringify(v) + ") 抛了").not.toThrow();
    }
  });

  it("不同畸形给出**不同**的观察串（否则「缺失」会被当成「卡在同一动作」）", () => {
    const shapes = [undefined, null, {}, ""].map((v) => stuckObservationOf(v));
    expect(new Set(shapes).size, "两种畸形折成同一个串 ⇒ 卡死判定会把它们当成重复").toBe(4);
  });

  it("正常字符串照旧截 200 字（既有口径不变）", () => {
    const long = "a".repeat(500);
    expect(stuckObservationOf(long)).toHaveLength(200);
  });

  it("环形对象不抛（JSON.stringify 会炸的那一类）", () => {
    const cyclic: Record<string, unknown> = {};
    cyclic.self = cyclic;
    expect(() => stuckObservationOf(cyclic)).not.toThrow();
  });
});

// M3c 卡死检测（agent-plan §4.4.8；OpenHands StuckDetector 取最廉两条 + 超时）。
// 检测器是纯函数（事件窗口 → verdict），可单测；心跳 = 子流 tool_call/tool_result 天然时间戳，
// 不造独立心跳事件。触发 → agent_status=waiting_input(reason=stuck) + agent_message 提醒，
// 人决定继续（resume 清除 stuck 态）/ 取消（既有取消链）；阈值可配（验收用短阈值）。

/** 卡死检测参数（缺省 = §4.4.8 定稿值；验收/演示可配短阈值）。 */
export interface StuckConfig {
  /** 规则一：同 action + 同 observation 连续出现次数上限（×4 触发）。 */
  maxActionObsRepeats: number;
  /** 规则二：同 action + error 连续出现次数上限（×3 触发）。 */
  maxActionErrorRepeats: number;
  /** 规则三：静默超时（子流无新事件；缺省 10 分钟）。 */
  silenceMs: number;
  /** 检测窗口内保留的最大轮数（内存帽）。 */
  windowSize: number;
}

export const DEFAULT_STUCK_CONFIG: StuckConfig = Object.freeze({
  maxActionObsRepeats: 4,
  maxActionErrorRepeats: 3,
  silenceMs: 10 * 60_000,
  windowSize: 16,
});

/** 一轮「动作 → 观察」：action = 工具名+参数摘要；observation = 结果摘要；ok = 是否成功。 */
export interface StuckTurn {
  action: string;
  observation: string;
  ok: boolean;
}

export type StuckVerdict =
  | { stuck: false }
  | { stuck: true; rule: "same_action_obs_x4" | "same_action_error_x3"; repeats: number; sameObservation: boolean };

/** 卡死判定（纯函数，规则一优先于规则二——OpenHands 同序）：
 *  - 规则一：最近 N 轮（maxActionObsRepeats）action 与 observation 全同 → stuck；
 *  - 规则二：最近 N 轮（maxActionErrorRepeats）action 全同且全部 error → stuck。
 *  轮数不足或配置非法（<2）→ 不判卡死（fail-open 于正常长任务，不会误伤单轮重复读）。
 *
 *  `sameObservation` 交的是**这一趟真比了什么**，不是推测：规则一按定义为 true；规则二从前只看
 *  `action` 相同＋全失败，却在对模型那句提示里断言「原样重试不会改变结果」——连败三次而每次错误不同
 *  （flaky 测试、超时、竞态）时那句话为假，而它恰好会把"该再看一次"的那次重试劝掉。
 *  比较用的是截断后的摘要（见 `stuckObservationOf`），所以这里也只声称"比对窗口内相同"。
 *  **窗口归调用方定，不归本模块**：`loop.ts` 喂的是前 200 字，而 `no-progress.ts#judgeNoProgressEvents`
 *  喂的是全串（那边注释明说截断前缀比会漏掉一条真实红）⇒ 「比对取前 200 字」这句措辞的出处在调用方，
 *  谁复用本模块都得按自己那根串重新说一次（第 313 页那条不变量：只声称真比过的那件事）。 */
export function detectStuck(turns: readonly StuckTurn[], config: StuckConfig = DEFAULT_STUCK_CONFIG): StuckVerdict {
  const nObs = Math.max(2, Math.floor(config.maxActionObsRepeats));
  const nErr = Math.max(2, Math.floor(config.maxActionErrorRepeats));
  if (turns.length >= nObs) {
    const window = turns.slice(-nObs);
    const first = window[0]!;
    if (window.every((t) => t.action === first.action && t.observation === first.observation && t.ok === first.ok)) {
      return { stuck: true, rule: "same_action_obs_x4", repeats: nObs, sameObservation: true };
    }
  }
  if (turns.length >= nErr) {
    const window = turns.slice(-nErr);
    const first = window[0]!;
    if (!first.ok && window.every((t) => t.action === first.action && t.ok === false)) {
      // 这一支的判据里**没有** observation ⇒ 它自己得说清"这几次错误是不是一样"，
      // 否则下游那句提示就只能靠猜（旧版就是这么把"每次错误不同"也说成"原样重试不会改变结果"的）。
      const sameObservation = window.every((t) => t.observation === first.observation);
      return { stuck: true, rule: "same_action_error_x3", repeats: nErr, sameObservation };
    }
  }
  return { stuck: false };
}

/** 循环引用安全的 JSON 摘要（**不许抛**：参数里有环时 JSON.stringify 直接抛 TypeError）。
 *  环处换成显式占位（与脱敏面同一口径："[循环引用]"），既不炸也不静默丢字段。 */
function safeJsonSummary(value: unknown, seen: WeakSet<object> = new WeakSet()): string {
  try {
    return JSON.stringify(value, (_key, v: unknown) => {
      if (typeof v === "object" && v !== null) {
        if (seen.has(v)) return "[循环引用]";
        seen.add(v);
      }
      return v;
    }) ?? "";
  } catch {
    // 兜底：带 getter 的对象、Proxy 陷阱等 stringify 也可能抛——摘要面不许因此炸掉整轮。
    return "[无法序列化]";
  }
}

/** 动作摘要（tool_call → 稳定可比的 action 串；参数截断防长参数抖动）。
 *
 *  **不许抛**（2026-10-19）：这一格曾被关在 `stuckNudge` 开关里，只有主会话那条路会调到它；
 *  开关打开后它**恒**被调（历史是判据的输入，与提示无关）⇒ 参数里带环的工具调用
 *  （诊断/影响面那种带 parent 指针的图）会让 `JSON.stringify` 抛 TypeError ⇒ 整轮任务死在
 *  这一次调用上。脱敏面早就处理过环（`redactValue` 的 WeakSet），这里跟同一口径。 */
export function stuckActionOf(name: string, args: Record<string, unknown>): string {
  return name + " " + safeJsonSummary(args).slice(0, 200);
}

/** 观察摘要（tool_result → 稳定可比的 observation 串；截断防长输出抖动）。 */
export function stuckObservationOf(output: string): string {
  return output.slice(0, 200);
}

